#pragma once

#include "bsp/pinEvent/pinEventConfiguration.h"

#include <pinEdge/IPinEdgeConsumer.h>

#if NX_PIN_EVENT_COUNT > 0
#include <pinEvent/PinEvent.h>
#endif

namespace bsp
{
/**
 * Pin-interrupt dispatcher of this family port (IO-52, bios::PinIrqDispatcher): its table, its instance, the
 * pin-detect handlers and - since IO-54 - the pin events of the project live in
 * bspConfiguration/src/bsp/pinIrq/PinIrqConfig.cpp. The table is generated by tools/bswgen from the project
 * (bsp/pinIrq/pinIrqConfiguration.h: Hall sensor sets and pin_events, vectors from the derivative fact
 * pin_interrupts).
 *
 * Start-up order, once, in startPinInterrupts(): armPinInterrupts() (vectors off, edges armed, stale flags
 * cleared), then every consumer starts from the levels it samples (Hall decoders, pin events), then
 * enablePinInterrupts() (NVIC levels, vectors on). The generated RTE calls startPinInterrupts() once when the project
 * has a Hall sensor it reads or pin events. Without a pin with a consumer in the project the functions do nothing.
 *
 * A reference to one of these functions also pulls the object with the handlers out of the static library: the
 * vector table declares the handlers weak, and a weak definition alone does not (IO-07).
 */
void armPinInterrupts();

void enablePinInterrupts();

/** arm -> Hall decoders and pin events start -> enable (see above); call once. */
void startPinInterrupts();

/**
 * Task side of the pin events (pinevent::PinEvents::cycle(): re-arm after the hold-off, expiry of a quiet history).
 * Called every cycle of one task (the generated RTE: the first task that reads a pin event, else the first
 * application task). Does nothing without pin events.
 */
void cyclePinEvents();

/** Arming of the pins of a consumer (IPinEdgeControl); without pins it reports every channel as unknown. */
::bsp::pinedge::IPinEdgeControl& pinEdgeControl();

#if NX_PIN_EVENT_COUNT > 0
/** The pin events of the project (read by the RTE and the console "pinevent"). */
::pinevent::PinEvents& pinEvents();
#endif

} // namespace bsp
